#!/usr/bin/env bash
set -euo pipefail

# Back up the current server.js
cp -a /opt/control-panel-backend/server.js /opt/control-panel-backend/server.js.bak.$(date +%Y%m%d%H%M%S)

# Generate a dedicated SSH key for the control panel to reach the Palworld VM
if [ ! -f /root/.ssh/palworld_ed25519 ]; then
    ssh-keygen -t ed25519 -N '' -f /root/.ssh/palworld_ed25519 -C 'control-panel@111'
fi

# Install the public key on VM 106 (append-only, deduplicate)
PUBKEY=$(cat /root/.ssh/palworld_ed25519.pub)
qm guest exec 106 -- sh -c "grep -qF '$PUBKEY' /home/aedefruscio/.ssh/authorized_keys || echo '$PUBKEY' >> /home/aedefruscio/.ssh/authorized_keys"

# Append the Palworld settings capability to server.js
cat >> /opt/control-panel-backend/server.js <<'EOF'

// ===== Palworld settings capability (ADD100) =====
const { execFileSync } = require('child_process');
const PALWORLD_IP = '192.168.1.106';
const PALWORLD_USER = 'aedefruscio';
const PALWORLD_KEY = '/root/.ssh/palworld_ed25519';
const PALWORLD_CONFIG = '/opt/palworld/DefaultPalWorldSettings.ini';

function palworldSsh(args, input) {
    return execFileSync('ssh', [
        '-i', PALWORLD_KEY,
        '-o', 'BatchMode=yes',
        '-o', 'StrictHostKeyChecking=yes',
        `${PALWORLD_USER}@${PALWORLD_IP}`,
        ...args
    ], { input, encoding: 'utf8', timeout: 15000 });
}

function palworldReadSettings() {
    const raw = palworldSsh(['cat', PALWORLD_CONFIG]);
    const settings = {};
    for (const line of raw.split('\n')) {
        const m = line.match(/^([A-Za-z0-9_]+)=(.*)$/);
        if (m) settings[m[1]] = m[2];
    }
    return settings;
}

function palworldWriteSettings(updates) {
    const current = palworldReadSettings();
    const merged = { ...current, ...updates };
    const body = Object.entries(merged)
        .map(([k, v]) => `${k}=${v}`)
        .join('\n') + '\n';
    palworldSsh(['sh', '-c', `cat > ${PALWORLD_CONFIG}`], body);
    return merged;
}

app.get('/api/palworld/settings', (req, res) => {
    try {
        res.json(palworldReadSettings());
    } catch (err) {
        res.status(502).json({ error: 'palworld-unreachable', detail: String(err.message || err) });
    }
});

app.put('/api/palworld/settings', (req, res) => {
    try {
        const updates = req.body;
        if (!updates || typeof updates !== 'object' || Array.isArray(updates)) {
            return res.status(400).json({ error: 'body must be a JSON object of key/value pairs' });
        }
        res.json(palworldWriteSettings(updates));
    } catch (err) {
        res.status(502).json({ error: 'palworld-unreachable', detail: String(err.message || err) });
    }
});
// ===== End Palworld settings capability =====
EOF

# Restart the control panel service
systemctl restart control-panel.service
